                function AddDays(datum, amount) {
                    /// <summary>Přidání dnů k datu</summary>
                    /// <param name="date" type="Date">Datum</param>
                    /// <param name="amount" type="Integer">Počet dnů</param>
                    /// <returns type="Date"> Datum </returns>
                    var tzOff = datum.getTimezoneOffset() * 60 * 1000, t = datum.getTime(), d = new Date(), tzOff2;
                    t += 1000 * 60 * 60 * 24 * amount;
                    d.setTime(t);
                    tzOff2 = d.getTimezoneOffset() * 60 * 1000;
                    if (tzOff !== tzOff2) {
                        var diff = tzOff2 - tzOff;
                        t += diff;
                        d.setTime(t);
                    }
                    return d;
                }
                GPokWebBase.AddDays = AddDays;
