                    returnGF.addTextColumn({ name: "ktg_dok_txt", fragment: "POKSPID", caption: "jres:31302028" }); //RC 31302028 : Kategorie dokladu "ktg_dok", "pokcktg","ktg_dok","ktg_dok_txt"
                    returnGF.addTextColumn({ name: "druh_dok_txt", fragment: "POKSPID", caption: "jres:31302029" }); //RC 31302029 : Druh dokladu "pokcdru","druh_dok","druh_dok_txt"
                    returnGF.addTextColumn({ name: "ixs_fun_nazev_rf", fragment: "POKSPID", caption: "Zpracovatel" });
