                                                    row.c_saldo = new Decimal(data.data[0].c_saldo ?? 0);
                                                    l_oReturnDto.push({ ixs_esu: row.ixs_esu, c_celkem: new Decimal(row.c_saldo), c_celkem_m: Decimal.mul(row.c_saldo, (that.model.kurz_doklad ?? 1)), vs: row.vs, ss: row.ss, ixp_buc: row.ixp, nazev_predpisu: platba.nazev_predpisu });
                                                    def.resolve(l_oReturnDto);
